func (p *parser) parseExpr(minPrec int) ast.Expr {
    left := p.parsePrefix()                        // null denotation
    for {
        op := p.tok
        if op.Precedence() < minPrec {
            return left
        }
        p.next()
        right := p.parseExpr(op.Precedence() + 1)  // left-associative
        left = &ast.BinaryExpr{X: left, OpPos: p.pos, Op: op, Y: right}
    }
}
